// Рядки Data Table: { id (автоінкремент), createdAt, updatedAt, ...колонки }. Порожній результат = [{}].
const rows = (items) => items.map((i) => i.json).filter((j) => j && j.id !== undefined && j.id !== null);

const cfg = $('Конфіг').first().json;
const tz = cfg.TIMEZONE || 'Europe/Kyiv';
const today = DateTime.now().setZone(tz);
const toKyiv = (v) => DateTime.fromJSDate(new Date(v)).setZone(tz);

// Активні реєстрації (без Cancelled) за сесіями
const counts = {};
for (const p of rows($('DT: активні реєстрації').all())) counts[p.session_id] = (counts[p.session_id] || 0) + 1;

// Відповідальні: employee_id → { name, discord_id }
const people = new Map(rows($('DT: відповідальні').all()).map((r) => [Number(r.employee_id), r]));
const parseIds = (v) => [...new Set(String(v === null || v === undefined ? '' : v).split(/[^0-9]+/).filter(Boolean).map(Number))];
// Тег у Discord: <@ID>. Без discord_id — лише ім'я жирним.
const mention = (id) => {
  const r = people.get(id);
  if (!r) return `співробітник #${id}`;
  const did = r.discord_id === null || r.discord_id === undefined ? '' : String(r.discord_id).trim();
  return /^\d+$/.test(did) ? `<@${did}>` : `**${String(r.name || '').trim() || '#' + id}**`;
};

const sessions = rows($('DT: усі сесії').all())
  .filter((s) => s.start_date)
  .map((s) => ({ s, start: toKyiv(s.start_date) }))
  .filter(({ start }) => start.isValid && start.hasSame(today, 'day'))
  .filter(({ s }) => cfg.INCLUDE_CLOSED !== false || s.status !== 'Closed')
  .sort((a, b) => a.start.toMillis() - b.start.toMillis());

const dateTitle = today.setLocale('uk').toFormat('cccc, d MMMM');
if (!sessions.length) {
  if (cfg.SEND_WHEN_EMPTY !== true) return []; // нічого не надсилаємо
  return [{ json: { content: `📅 **Співбесіди на сьогодні (${dateTitle})**\nСьогодні співбесід немає.` } }];
}

const base = String(cfg.ADMIN_PANEL_URL || '').trim().replace(/\/+$/, '');
const blocks = sessions.map(({ s, start }) => {
  const max = Number(s.max_participants) || 0;
  const count = counts[s.session_id] || 0;
  const ids = parseIds(s.responsible_ids);
  const lines = [
    `🕒 **${start.toFormat('HH:mm')}** · ${s.pipeline_name || s.session_name || 'Співбесіда'}${s.status === 'Closed' ? ' · 🔒 закрита' : ''}`,
    `👥 Записано: ${count}${max ? ' з ' + max : ''}`,
    `👤 Відповідальні: ${ids.length ? ids.map(mention).join(', ') : '⚠️ не призначено'}`,
  ];
  if (base) lines.push(`🔗 <${base}/sessions/${encodeURIComponent(s.session_id)}>`);
  return lines.join('\n');
});

// Discord: до 2000 символів на повідомлення — ділимо за сесіями
const header = `📅 **Співбесіди на сьогодні (${dateTitle})** — ${sessions.length}`;
const LIMIT = 1900;
const messages = [];
let cur = header;
for (const b of blocks) {
  if ((cur + '\n\n' + b).length > LIMIT) { messages.push(cur); cur = '📅 **Співбесіди на сьогодні (продовження)**'; }
  cur += '\n\n' + b;
}
messages.push(cur);
return messages.map((content) => ({ json: { content } }));
